export const CATALOG_SKUS: SKU[] = RAW_DATA.map((line, index) => {
  const [seriesId, articleCode, ...descParts] = line.split('\t');
  const description = descParts.join('\t').trim();
  return { id: 'cat-' + index, seriesId: seriesId, articleCode: articleCode.trim(), description: description, availability: 'on_request' };
});